    Swap_Bros_Mod.Main.LoadCustomBros();
    Swap_Bros_Mod.Main.CreateBroList();
    var l = Swap_Bros_Mod.Main.currentBroList;
    for (int i = 0; i < 4; i++) { int ix = l.IndexOf(p[2 + i]); set.selGridInt[i] = ix < 0 ? 0 : ix; }
