public class UimBusyHold : MonoBehaviour
{
    public int Ms;

    void Update()
    {
        int ms = Ms;
        Ms = 0;
        if (ms <= 0) return;
        Destroy(gameObject);
        System.Threading.Thread.Sleep(ms);
    }
}
